const isObj = (v) => !!v && typeof v === 'object' && !Array.isArray(v);
const str = (v) => {
  if (typeof v === 'string' && v.trim()) return v.trim();
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return null;
};
const first = (...vals) => {
  for (const v of vals) { const s = str(v); if (s !== null) return s; }
  return null;
};

const body = isObj($json.body) ? $json.body : $json;
const contact = [body.contact, body.data, body.payload].find(isObj) || body;
const conversation = [body.conversation, contact.conversation].find(isObj) || {};
const message = [body.message, body.data && body.data.message].find(isObj) || {};

const contactId = first(
  contact.id, contact.contact_id, contact.contactId,
  body.contact_id, body.contactId
);
if (!contactId) {
  throw new Error('No Respond.io contact id in payload: ' + JSON.stringify(body).slice(0, 500));
}

const contactName = first(
  contact.name, contact.full_name, contact.fullName,
  [str(contact.firstName || contact.first_name), str(contact.lastName || contact.last_name)]
    .filter(Boolean).join(' ')
);

// Direction, read defensively. The New Outgoing Message trigger only fires for outgoing
// messages and Respond.io puts 'traffic' on the message, but the field has moved between
// payload versions, so this normalizes whatever is present to outgoing / incoming /
// unknown. The If node downstream drops only a definite 'incoming' -- see its note.
const rawTraffic = first(message.traffic, body.traffic, message.direction, body.direction);
const isOutgoingFlag = [message.isOutgoing, body.isOutgoing, message.is_outgoing, body.is_outgoing]
  .find((v) => typeof v === 'boolean');
let traffic = 'unknown';
if (rawTraffic) {
  const t = rawTraffic.toLowerCase();
  if (t === 'outgoing' || t === 'out' || t === 'sent') traffic = 'outgoing';
  else if (t === 'incoming' || t === 'in' || t === 'received') traffic = 'incoming';
} else if (typeof isOutgoingFlag === 'boolean') {
  traffic = isOutgoingFlag ? 'outgoing' : 'incoming';
}

// A message id makes the SIMS idempotency key exact. Without one the key falls back to
// event type + contact + timestamp + conversation, and two agent messages inside the
// same timestamp would collide -- harmless here (the second is a no-op anyway) but it
// hides the delivery in the event log.
const eventId = first(
  message.id, message.message_id, message.messageId,
  body.message_id, body.messageId,
  body.event_id, body.eventId, body.id
);
const occurredAt = first(
  message.timestamp, message.created_at, message.createdAt,
  body.occurred_at, body.occurredAt, body.timestamp, body.created_at, body.updated_at
) || new Date().toISOString();

return {
  json: {
    event_type: 'message.sent',
    event_id: eventId,
    occurred_at: occurredAt,
    traffic,
    contact: {
      id: contactId,
      name: contactName,
      email: first(contact.email, contact.contact_email),
      phone: first(contact.phone, contact.phone_number, contact.phoneNumber),
    },
    conversation: {
      conversation_id: first(conversation.id, conversation.conversation_id, body.conversation_id, body.conversationId),
    },
  },
};
